  "k8s/professional/tls-server.yaml": "apiVersion: \"cert-manager.io/v1\"\nkind: \"Issuer\"\nmetadata:\n  name: \"learning-ca\"\n  namespace: \"kubelab-deep\"\nspec:\n  ca:\n    secretName: \"learning-ca\"\n---\napiVersion: \"cert-manager.io/v1\"\nkind: \"Certificate\"\nmetadata:\n  name: \"deep-localhost\"\n  namespace: \"kubelab-deep\"\nspec:\n  secretName: \"deep-localhost\"\n  dnsNames:\n    - \"localhost\"\n    - \"deep-gateway\"\n    - \"deep-gateway.kubelab-deep.svc\"\n  duration: \"24h\"\n  renewBefore: \"8h\"\n  privateKey:\n    rotationPolicy: \"Always\"\n  issuerRef:\n    name: \"learning-ca\"\n    kind: \"Issuer\"\n---\napiVersion: \"networking.k8s.io/v1\"\nkind: \"Ingress\"\nmetadata:\n  name: \"deep-route\"\n  namespace: \"kubelab-deep\"\n  annotations:\n    kubernetes.io/ingress.class: \"kubelab-deep\"\nspec:\n  rules:\n    -\n      host: \"localhost\"\n      http:\n        paths:\n          -\n            path: \"/\"\n            pathType: \"Prefix\"\n            backend:\n              service:\n                name: \"deep-web\"\n                port:\n                  number: 3000\n  tls:\n    -\n      hosts:\n        - \"localhost\"\n      secretName: \"deep-localhost\"\n",
  "k8s/professional/bao.yaml": "apiVersion: \"v1\"\nkind: \"ServiceAccount\"\nmetadata:\n  name: \"deep-bao\"\n  namespace: \"kubelab-deep\"\nautomountServiceAccountToken: false\n---\napiVersion: \"rbac.authorization.k8s.io/v1\"\nkind: \"ClusterRoleBinding\"\nmetadata:\n  name: \"kubelab-deep-bao-reviewer\"\nsubjects:\n  -\n    kind: \"ServiceAccount\"\n    name: \"deep-bao\"\n    namespace: \"kubelab-deep\"\nroleRef:\n  apiGroup: \"rbac.authorization.k8s.io\"\n  kind: \"ClusterRole\"\n  name: \"system:auth-delegator\"\n---\napiVersion: \"v1\"\nkind: \"ConfigMap\"\nmetadata:\n  name: \"bao-config\"\n  namespace: \"kubelab-deep\"\ndata:\n  server.hcl: \"disable_mlock = true\\n\"\n---\napiVersion: \"apps/v1\"\nkind: \"Deployment\"\nmetadata:\n  name: \"deep-bao\"\n  namespace: \"kubelab-deep\"\nspec:\n  replicas: 1\n  selector:\n    matchLabels:\n      app: \"deep-bao\"\n  template:\n    metadata:\n      labels:\n        app: \"deep-bao\"\n        kubelab.local/monitor: \"yes\"\n    spec:\n      automountServiceAccountToken: true\n      securityContext:\n        runAsNonRoot: true\n        runAsUser: 1000\n        runAsGroup: 1000\n        fsGroup: 1000\n        seccompProfile:\n          type: \"RuntimeDefault\"\n      containers:\n        -\n          name: \"bao\"\n          image: \"openbao/openbao:2.7.2\"\n          command:\n            - \"bao\"\n          args:\n            - \"server\"\n            - \"-dev\"\n            - \"-dev-root-token-id=kubelab-fictional-root\"\n            - \"-dev-listen-address=0.0.0.0:8200\"\n            - \"-config=/config/server.hcl\"\n          env:\n            -\n              name: \"BAO_ADDR\"\n              value: \"http://127.0.0.1:8200\"\n            -\n              name: \"BAO_TOKEN\"\n              value: \"kubelab-fictional-root\"\n            -\n              name: \"HOME\"\n              value: \"/tmp\"\n          ports:\n            -\n              containerPort: 8200\n          resources:\n            requests:\n              cpu: \"25m\"\n              memory: \"48Mi\"\n            limits:\n              cpu: \"500m\"\n              memory: \"256Mi\"\n          securityContext:\n            allowPrivilegeEscalation: false\n            readOnlyRootFilesystem: true\n            capabilities:\n              drop:\n                - \"ALL\"\n          volumeMounts:\n            -\n              name: \"config\"\n              mountPath: \"/config\"\n              readOnly: true\n            -\n              name: \"tmp\"\n              mountPath: \"/tmp\"\n              readOnly: false\n          readinessProbe:\n            httpGet:\n              path: \"/v1/sys/health\"\n              port: 8200\n            periodSeconds: 2\n      volumes:\n        -\n          name: \"config\"\n          configMap:\n            name: \"bao-config\"\n        -\n          name: \"tmp\"\n          emptyDir:\n            sizeLimit: \"32Mi\"\n      serviceAccountName: \"deep-bao\"\n---\napiVersion: \"v1\"\nkind: \"Service\"\nmetadata:\n  name: \"deep-bao\"\n  namespace: \"kubelab-deep\"\nspec:\n  selector:\n    app: \"deep-bao\"\n  ports:\n    -\n      name: \"http\"\n      port: 8200\n      targetPort: 8200\n",
  "k8s/professional/admission-policy.yaml": "apiVersion: \"admissionregistration.k8s.io/v1\"\nkind: \"ValidatingAdmissionPolicy\"\nmetadata:\n  name: \"kubelab-owner\"\nspec:\n  failurePolicy: \"Fail\"\n  matchConstraints:\n    resourceRules:\n      -\n        apiGroups:\n          - \"apps\"\n        apiVersions:\n          - \"v1\"\n        operations:\n          - \"CREATE\"\n          - \"UPDATE\"\n        resources:\n          - \"deployments\"\n  validations:\n    -\n      expression: \"has(object.metadata.labels) && 'owner' in object.metadata.labels\"\n      message: \"Learning workloads must declare metadata.labels.owner\"\n---\napiVersion: \"admissionregistration.k8s.io/v1\"\nkind: \"ValidatingAdmissionPolicyBinding\"\nmetadata:\n  name: \"kubelab-owner\"\nspec:\n  policyName: \"kubelab-owner\"\n  validationActions:\n    - \"Deny\"\n  matchResources:\n    namespaceSelector:\n      matchLabels:\n        kubelab.local/admission: \"enabled\"\n",
  "k8s/professional/policy-rejected.yaml": "apiVersion: \"apps/v1\"\nkind: \"Deployment\"\nmetadata:\n  name: \"policy-example\"\n  namespace: \"kubelab-deep\"\nspec:\n  replicas: 1\n  selector:\n    matchLabels:\n      app: \"policy-example\"\n  template:\n    metadata:\n      labels:\n        app: \"policy-example\"\n        kubelab.local/monitor: \"yes\"\n    spec:\n      automountServiceAccountToken: false\n      securityContext:\n        runAsNonRoot: true\n        runAsUser: 1000\n        runAsGroup: 1000\n        fsGroup: 1000\n        seccompProfile:\n          type: \"RuntimeDefault\"\n      containers:\n        -\n          name: \"web\"\n          image: \"kubelab:deep\"\n          imagePullPolicy: \"Never\"\n          command:\n            - \"node\"\n            - \"labs/telemetry/app.mjs\"\n          ports:\n            -\n              name: \"http\"\n              containerPort: 3000\n          resources:\n            requests:\n              cpu: \"25m\"\n              memory: \"48Mi\"\n            limits:\n              cpu: \"500m\"\n              memory: \"256Mi\"\n          securityContext:\n            allowPrivilegeEscalation: false\n            readOnlyRootFilesystem: true\n            capabilities:\n              drop:\n                - \"ALL\"\n",
